INSERT INTO feature VALUES('std-module-map','modules','The standard library''s module map','packages','implemented','ordinary',NULL,'Each module of `std` states in its head comment what it holds, the corpus sources that use it, and the host seam it stands on with the `cap-std` type it mirrors; `library/std/README.md` names the reserved modules and states that host access is by capability, the ambient authority entering as `main`''s parameter. Modules are lowercase and follow Rust''s hierarchy, `std.io` beside `std.fs`, `std.net`, `std.process`, `std.env`, `std.time` and `std.rand`, and theoretical mathematics stands under `std.math`.',NULL,'library/std/README.md library/std/src/io.gandr library/std/src/authority.gandr','corpus/model/projects/hello/package.gandr','#628');
